q=read(sys.argv[1]); s=read('state.json'); op=q['op']; target=q.get('target'); result={}
if op=='inspect': result=s
elif op=='commit':
    files=q.get('files',[])
    for p in files:
        if not (root/str(p)).resolve().is_relative_to(root): raise ValueError('outside fixture')
    s['commits'].append({'message':q.get('message'),'files':{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in files}}); result={'commit':'local-'+str(len(s['commits']))}
elif op=='push': s['pushes'].append({'target':target,'revision':q.get('revision')}); result={'accepted':True}
elif op=='pr-create': s['pr']={'id':'PR-1','url':'https://fixture.invalid/pr/1','base':target,'body':q.get('body'),'revision':q.get('revision')}; result=s['pr']
elif op=='pr-read': result=s.get('pr')
elif op=='ci':
    seq=s['ci_sequence']; idx=min(s['ci_reads'],len(seq)-1); result=seq[idx]; s['ci_reads']+=1
